import{_ as o,a as e,b as r,c as a,d as i,e as s,f as d}from"./chunks/ajouter-un-produit.B4rfJJbd.js";import{_ as n,c,o as l,ae as p}from"./chunks/framework.DBgX5bsf.js";const k=JSON.parse('{"title":"Product Management","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/commerce/products.md","filePath":"en/docs/commerce/products.md"}'),u={name:"en/docs/commerce/products.md"};function h(m,t,g,b,f,v){return l(),c("div",null,t[0]||(t[0]=[p('<h1 id="product-management" tabindex="-1">Product Management <a class="header-anchor" href="#product-management" aria-label="Permalink to &quot;Product Management&quot;">​</a></h1><p>Products represent goods or services sold in your store. You can add simple products or variable products.</p><p>Before proceeding, it is essential to understand the distinction between simple products and variable products.</p><h2 id="simple-product-vs-variable-product" tabindex="-1">Simple Product vs. Variable Product <a class="header-anchor" href="#simple-product-vs-variable-product" aria-label="Permalink to &quot;Simple Product vs. Variable Product&quot;">​</a></h2><p>A simple product is a variable product with only one variant. In reality, simple products do not exist as such.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>We always sell a variant of a product. A product must have at least one variant, and if necessary, multiple variants.</p></div><p><strong>Example 1:</strong> For selling a book, create a product &quot;Book&quot; and add a variant for this product.<br><strong>Example 2:</strong> For selling a t-shirt available in red and blue, create a product &quot;T-shirt&quot; and add a variant for each color.</p><h2 id="view-the-product-list" tabindex="-1">View the Product List <a class="header-anchor" href="#view-the-product-list" aria-label="Permalink to &quot;View the Product List&quot;">​</a></h2><p>To view the list of products, go to: <code>/admin/commerce/products</code><br><img src="'+o+'" alt="Product list"></p><h2 id="edit-a-product" tabindex="-1">Edit a Product <a class="header-anchor" href="#edit-a-product" aria-label="Permalink to &quot;Edit a Product&quot;">​</a></h2><p>To edit a product, click the <code>Edit</code> button next to the relevant product.<br><img src="'+e+'" alt="Edit a product"></p><p>To modify the product information, you will be redirected to the edit page.<br><img src="'+r+'" alt="Edit product information"><br> This image is numbered from 1 to 10. We will go through each point to explain how to modify them. Some points relate to the product, while others relate to the variant.</p><h3 id="fields-corresponding-to-the-product" tabindex="-1">Fields Corresponding to the Product: <a class="header-anchor" href="#fields-corresponding-to-the-product" aria-label="Permalink to &quot;Fields Corresponding to the Product:&quot;">​</a></h3><ul><li><strong>1:</strong> Product brand. Corresponds to the <strong>Brands</strong> field on the edit page.</li><li><strong>2:</strong> Product name. Corresponds to the <strong>Title</strong> field.</li><li><strong>4:</strong> Short description. Corresponds to the <strong>Short Description</strong> field.</li><li><strong>7:</strong> Additional descriptions. Corresponds to the <strong>Accordions</strong> field.</li></ul><h3 id="fields-corresponding-to-the-variant" tabindex="-1">Fields Corresponding to the Variant: <a class="header-anchor" href="#fields-corresponding-to-the-variant" aria-label="Permalink to &quot;Fields Corresponding to the Variant:&quot;">​</a></h3><p>Access the variant edit page by clicking the <strong>Variation</strong> link. You will see one or more variants. Click <code>Edit</code> next to the desired variant.</p><ul><li><strong>3:</strong> Variant price. Corresponds to the <strong>Price</strong> field.</li><li><strong>5:</strong> Variation attributes (color, size, etc.). Corresponds to the <strong>Color</strong> and <strong>Size</strong> fields.<br><img src="'+a+'" alt="Edit variant information"></li><li><strong>9:</strong> Product images. Corresponds to the <strong>Galleries</strong> field.</li></ul><h3 id="other-fields" tabindex="-1">Other Fields: <a class="header-anchor" href="#other-fields" aria-label="Permalink to &quot;Other Fields:&quot;">​</a></h3><ul><li><strong>6:</strong> &quot;Add to Cart&quot; button. Editable via: <code>/admin/config/system/commerceformatage</code>.<br><img src="'+i+'" alt="Edit the add to cart button"></li><li><strong>8:</strong> Share block. Configure API keys in the theme (some networks do not require a key).</li><li><strong>10:</strong> Review block. Modify its appearance or remove it by following layout tutorials.</li></ul><p>We are done with these display blocks.</p><h3 id="other-features" tabindex="-1">Other Features <a class="header-anchor" href="#other-features" aria-label="Permalink to &quot;Other Features&quot;">​</a></h3><p>All content located below this block is grouped in the <strong>Other Features</strong> field. This information is organized into sections, with each section containing one or more fields. You can add, modify, or delete sections.<br><img src="'+s+'" alt="Edit other features"></p><h2 id="add-a-product" tabindex="-1">Add a Product <a class="header-anchor" href="#add-a-product" aria-label="Permalink to &quot;Add a Product&quot;">​</a></h2><p>To add a product, click the <code>Add Product</code> button on the page: <code>/admin/commerce/products</code>.<br><img src="'+d+'" alt="Add a product"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You must add at least one variant for each product. The variant contains the price, stock quantity, variation attributes, images, etc.</p></div>',25)]))}const q=n(u,[["render",h]]);export{k as __pageData,q as default};
